package dev.admutium.techmod.test;
import dev.admutium.techmod.suit.*;import dev.admutium.techmod.machine.*;import dev.admutium.techmod.energy.*;
import net.fabricmc.fabric.api.gametest.v1.GameTest;import net.minecraft.gametest.framework.GameTestHelper;import net.minecraft.core.*;import net.minecraft.world.item.*;import net.minecraft.world.level.block.Blocks;import net.minecraft.nbt.NbtOps;import net.minecraft.world.entity.EquipmentSlot;
public final class SuitGameTests {
 private MachineBlockEntity machine(GameTestHelper h,MachineKind kind,int x,Direction facing){var pos=new BlockPos(x,1,1);h.setBlock(pos,Machines.BLOCKS.get(kind).defaultBlockState().setValue(MachineBlock.FACING,facing));var be=(MachineBlockEntity)h.getLevel().getBlockEntity(h.absolutePos(pos));EnergyNetwork.register(h.getLevel(),be);return be;}
 private net.minecraft.server.level.ServerPlayer survivor(GameTestHelper h){var p=(net.minecraft.server.level.ServerPlayer)h.makeMockServerPlayer(net.minecraft.world.level.GameType.SURVIVAL);var connection=new net.minecraft.network.Connection(net.minecraft.network.protocol.PacketFlow.SERVERBOUND);new io.netty.channel.embedded.EmbeddedChannel(connection);var cookie=net.minecraft.server.network.CommonListenerCookie.createInitial(p.getGameProfile(),false);h.getLevel().getServer().getPlayerList().placeNewPlayer(connection,p,cookie);p.gameMode.changeGameModeForPlayer(net.minecraft.world.level.GameType.SURVIVAL);p.connection.handleAcceptPlayerLoad(new net.minecraft.network.protocol.game.ServerboundPlayerLoadedPacket());return p;}
 private ItemStack suit(){var stack=new ItemStack(Suits.ITEM);Suits.ensure(stack);return stack;}
 @GameTest public void suitStartsEmptyAndCannotBeDispenserEquipped(GameTestHelper h){var item=suit();var data=Suits.ensure(item);h.assertTrue(data.energy()==0&&data.levels().isEmpty(),"Suit unexpectedly starts upgraded/charged");var eq=item.get(net.minecraft.core.component.DataComponents.EQUIPPABLE);h.assertTrue(!eq.dispensable()&&!eq.swappable()&&!eq.equipOnInteract(),"Suit can bypass service station");h.succeed();}
 @GameTest public void stateRoundTripIncludesInventoryFiltersAndCooldown(GameTestHelper h){var stack=suit();var s=new SuitSession(stack);s.upgrade(SuitUpgrade.INVENTORY);s.energy=123*Energy.UNIT;s.cargo.set(4,new ItemStack(Items.DIAMOND,17));s.blacklist.add("minecraft:cobblestone");s.ores.add("minecraft:diamond_ore");s.rescueReady=1234567;s.home=java.util.Optional.of(GlobalPos.of(h.getLevel().dimension(),h.absolutePos(new BlockPos(2,1,2))));s.nutrients=191;s.levels.put("nutrients",6);s.sealed=true;s.salvage.add(new ItemStack(Items.GOLD_INGOT,9));s.flush();var ops=h.getLevel().registryAccess().createSerializationContext(NbtOps.INSTANCE);var encoded=ItemStack.CODEC.encodeStart(ops,stack).getOrThrow();var decoded=ItemStack.CODEC.parse(ops,encoded).getOrThrow();var restored=new SuitSession(decoded);h.assertTrue(restored.id.equals(s.id)&&restored.energy==s.energy&&restored.cargo.get(4).getCount()==17&&restored.salvage.getFirst().getCount()==9&&restored.nutrients==191&&restored.rescueReady==1234567&&restored.home.equals(s.home)&&restored.blacklist.equals(s.blacklist),"Suit data lost during serialization");h.succeed();}
 @GameTest public void stationChargesFromRealNetworkWithoutCreatingEnergy(GameTestHelper h){var generator=machine(h,MachineKind.GENERATOR,1,Direction.WEST);var station=machine(h,MachineKind.STATION,2,Direction.EAST);station.setItem(0,suit());generator.energy=100*Energy.UNIT;for(int i=0;i<20;i++)EnergyNetwork.tick(h.getLevel());long charge=Suits.ensure(station.getItem(0)).energy();h.assertTrue(charge>0&&generator.energy+station.energy+charge==100*Energy.UNIT,"Station duplicated/lost charge");h.assertTrue(station.outgoing==0,"Station feeds energy back to the grid");h.succeed();}
 @GameTest public void creativeSourceHasFastDirectOutputButNoSurvivalDrop(GameTestHelper h){var source=machine(h,MachineKind.CREATIVE_SOURCE,1,Direction.WEST);var station=machine(h,MachineKind.STATION,2,Direction.EAST);for(int i=0;i<20;i++)EnergyNetwork.tick(h.getLevel());h.assertTrue(station.energy==512L*Energy.UNIT,"Creative source does not feed station at 512 TE/s");h.assertTrue(source.portLimit()==8192L*Energy.UNIT/20,"Creative output not fast");h.getLevel().destroyBlock(source.getBlockPos(),true);h.assertTrue(h.getLevel().getEntitiesOfClass(net.minecraft.world.entity.item.ItemEntity.class,new net.minecraft.world.phys.AABB(source.getBlockPos()).inflate(2)).stream().noneMatch(e->e.getItem().is(Machines.ITEMS.get(MachineKind.CREATIVE_SOURCE))),"Creative source dropped a survival item");h.succeed();}
 @GameTest public void upgradesPermanentAndEnergyBudgetCannotGoNegative(GameTestHelper h){var stack=suit();var s=new SuitSession(stack);for(int i=0;i<50;i++)s.upgrade(SuitUpgrade.MINING);h.assertTrue(s.level(SuitUpgrade.MINING)==20,"Mining exceeds 100%");s.energy=10*Energy.UNIT;h.assertTrue(!s.spend(11,0)&&s.energy==10*Energy.UNIT,"Failed operation consumed energy");h.assertTrue(s.spend(5,0)&&s.energy==5*Energy.UNIT,"Incorrect energy debit");s.flush();h.assertTrue(new SuitSession(stack).level(SuitUpgrade.MINING)==20,"Upgrades disappeared");h.succeed();}
 @GameTest public void rollingConsumptionIsActualEnergyPerSecond(GameTestHelper h){var s=new SuitSession(suit());s.energy=s.capacity();for(int i=0;i<20;i++){s.startTick();s.spend(.5,0);s.spend(.25,3);s.endTick();}h.assertTrue(s.rates[0]==10*Energy.UNIT&&s.rates[3]==5*Energy.UNIT,"Rates are not actual TE/s");for(int i=0;i<20;i++){s.startTick();s.endTick();}h.assertTrue(java.util.Arrays.stream(s.rates).sum()==0,"Idle rate did not decay");h.succeed();}
 @GameTest public void cargoMergesWithoutDuplicatingOrNestingSuits(GameTestHelper h){var s=new SuitSession(suit());s.upgrade(SuitUpgrade.INVENTORY);var input=new ItemStack(Items.DIAMOND,64);s.insertCargo(input);h.assertTrue(input.isEmpty()&&s.cargo.get(0).getCount()==64,"Cargo did not consume incoming stack");var nested=suit();s.insertCargo(nested);h.assertTrue(nested.getCount()==1&&s.cargo.get(1).isEmpty(),"Nested suit allowed");s.flush();h.assertTrue(Suits.ensure(s.stack).contents().cargo().getFirst().getCount()==64,"Cargo not saved");h.succeed();}
 @GameTest public void sealedRecoveryOnlyClearsItemsActuallyAccepted(GameTestHelper h){var station=machine(h,MachineKind.STATION,2,Direction.NORTH);var player=h.makeMockPlayer(net.minecraft.world.level.GameType.SURVIVAL);var stack=suit();var s=new SuitSession(stack);s.sealed=true;s.salvage.add(new ItemStack(Items.DIAMOND,23));s.flush();station.setItem(0,stack);player.setPos(station.getBlockPos().getX(),station.getBlockPos().getY(),station.getBlockPos().getZ());for(int i=0;i<36;i++)player.getInventory().setItem(i,new ItemStack(Items.STONE,64));var menu=new SuitStationMenu(1,player.getInventory(),station);menu.action("recover","");h.assertTrue(Suits.ensure(stack).sealed()&&Suits.ensure(stack).contents().salvage().getFirst().getCount()==23,"Recovery erased inaccessible items");player.getInventory().setItem(0,ItemStack.EMPTY);menu.action("recover","");h.assertTrue(!Suits.ensure(stack).sealed()&&Suits.ensure(stack).contents().salvage().isEmpty()&&player.getInventory().getItem(0).getCount()==23,"Recovery duplicated or lost items");h.succeed();}
 @GameTest public void stationEquipRemovePreservesIdentityAndCharge(GameTestHelper h){var be=machine(h,MachineKind.STATION,2,Direction.NORTH);var player=h.makeMockPlayer(net.minecraft.world.level.GameType.SURVIVAL);player.setPos(be.getBlockPos().getX(),be.getBlockPos().getY(),be.getBlockPos().getZ());var item=suit();var s=new SuitSession(item);s.energy=321*Energy.UNIT;s.flush();be.setItem(0,item);var menu=new SuitStationMenu(1,player.getInventory(),be);menu.action("equip","");h.assertTrue(be.getItem(0).isEmpty()&&Suits.worn(player)==item,"Equip did not transfer atomically");menu.action("remove","");h.assertTrue(Suits.worn(player).isEmpty()&&be.getItem(0)==item&&Suits.ensure(item).energy()==321*Energy.UNIT,"Remove changed charge/identity");h.succeed();}

 @GameTest public void shieldConsumesEnergyAndCannotProtectWithoutCharge(GameTestHelper h){var p=survivor(h);var item=suit();var s=new SuitSession(item);s.levels.put("shield",5);s.levels.put("shield_strength",5);s.shield=50;s.energy=100*Energy.UNIT;s.flush();p.setItemSlot(EquipmentSlot.CHEST,item);var runtime=Suits.session(p);float reduced=SuitRuntime.reduce(p,p.damageSources().generic(),10);h.assertTrue(reduced<1&&runtime.energy<100*Energy.UNIT&&runtime.shield<50,"Shield did not spend real energy");runtime.energy=0;h.assertTrue(SuitRuntime.reduce(p,p.damageSources().generic(),10)==10,"Empty suit still protected");h.succeed();}
 @GameTest public void lethalRecoveryHasPersistentFiveMinuteCooldown(GameTestHelper h){var p=survivor(h);var item=suit();var s=new SuitSession(item);s.levels.put("rescue",1);s.energy=10000*Energy.UNIT;s.flush();p.setItemSlot(EquipmentSlot.CHEST,item);p.setHealth(2);p.hurtServer(h.getLevel(),p.damageSources().genericKill(),1000);h.assertTrue(p.isAlive()&&p.getHealth()==p.getMaxHealth()*.75f,"Lethal rescue failed: health="+p.getHealth()+" alive="+p.isAlive()+" energy="+Suits.session(p).energy+" mode="+p.gameMode());var restored=Suits.session(p);h.assertTrue(restored.energy==7000*Energy.UNIT&&restored.rescueReady>System.currentTimeMillis()+290000,"Rescue cost/cooldown incorrect");h.assertTrue(p.getAttachedOrCreate(SuitRuntime.RESCUE)==restored.rescueReady,"Changing suits can bypass cooldown");h.succeed();}
 @GameTest public void deathStoresInventoryOnceInPersistentSuitRemains(GameTestHelper h){var p=survivor(h);p.setPos(net.minecraft.world.phys.Vec3.atCenterOf(h.absolutePos(new BlockPos(2,1,2))));var item=suit();var s=new SuitSession(item);s.energy=777*Energy.UNIT;s.levels.put("inventory",1);s.cargo.set(0,new ItemStack(Items.EMERALD,7));s.flush();p.setItemSlot(EquipmentSlot.CHEST,item);p.getInventory().setItem(0,new ItemStack(Items.DIAMOND,19));p.die(p.damageSources().generic());var all=h.getLevel().getEntitiesOfClass(SuitRemains.class,p.getBoundingBox().inflate(3));h.assertTrue(all.size()==1,"No unique suit remains");var remains=all.getFirst();var d=Suits.ensure(remains.getItem());h.assertTrue(d.sealed()&&d.energy()==777*Energy.UNIT&&d.contents().salvage().stream().filter(i->i.is(Items.DIAMOND)).mapToInt(ItemStack::getCount).sum()==19&&d.contents().cargo().getFirst().getCount()==7,"Death lost/duplicated inventory");h.assertTrue(p.getInventory().isEmpty(),"Death inventory still present");remains.playerTouch(p);h.assertTrue(!remains.isRemoved(),"Corpse auto-equipped on touch");for(int i=0;i<6020;i++)remains.tick();h.assertTrue(!remains.isRemoved(),"Suit despawned like ordinary loot");h.succeed();}
 @GameTest public void blackoutRestoresGravityFlightAbilities(GameTestHelper h){var p=survivor(h);p.getAbilities().mayfly=false;p.getAbilities().flying=false;var item=suit();var s=new SuitSession(item);s.energy=100*Energy.UNIT;s.levels.put("flight",3);s.active.add("flight_gravity");s.flush();p.setItemSlot(EquipmentSlot.CHEST,item);SuitRuntime.tick(p);h.assertTrue(p.getAbilities().mayfly&&p.getAbilities().flying,"Gravity did not enable flight");Suits.session(p).energy=0;SuitRuntime.tick(p);h.assertTrue(!p.getAbilities().mayfly&&!p.getAbilities().flying,"Power loss granted permanent free flight");h.succeed();}
 @GameTest public void capsuleCompartmentNeverMakesOversizedStacks(GameTestHelper h){var p=survivor(h);var item=suit();var s=new SuitSession(item);s.levels.put("nutrients",6);s.nutrients=192;s.flush();p.setItemSlot(EquipmentSlot.CHEST,item);var runtime=Suits.session(p);var menu=new SuitInventoryMenu(1,p.getInventory(),runtime);h.assertTrue(menu.slots.get(9).getItem().getCount()==64,"Compartment created illegal 192-item stack");menu.clicked(9,0,net.minecraft.world.inventory.ContainerInput.PICKUP,p);h.assertTrue(menu.getCarried().getCount()==64&&runtime.nutrients==128,"Capsules duplicated on extraction");menu.clicked(9,0,net.minecraft.world.inventory.ContainerInput.PICKUP,p);h.assertTrue(menu.getCarried().isEmpty()&&runtime.nutrients==192,"Capsules duplicated on insertion");h.succeed();}
}
